textfix["Yuck!"] = "Kinh quá!"
textfix["Nature giveth, and nature grosseth."] = "Thiên nhiên ban tặng và thiên nhiên tổng hợp."
textfix["If only I had crazy glue."] = "Giá như tôi có keo điên."
