textfix["Bird attack!"] = "Chim tấn công!"
textfix["You're deer meat!"] = "Bạn là thịt hươu!"
textfix["It's you or me!"] = "Đó là bạn hay tôi!"
textfix["Stupid pig!"] = "Heo ngốc!"
textfix["Get over here!"] = "Nhận hơn ở đây!"
textfix["Grrrrar!"] = "Grrrrar!"
textfix["Ew, kill iiiit!"] = "Ew, giết iiiit!"
