textfix["Your \"Royal Highness\""] = "\"Hoàng thân\" của bạn"
textfix["\"To change?\" No. It's a name..."] = "\"Thay đổi?\" Không. Đó là một cái tên..."
textfix["\"Alter\"?"] = "\"Thay đổi\"?"
textfix["\"Thataway\"... Ugh!"] = "\"Rời đi\"... Ugh!"
