textfix["\"YOU ARE HERE\""] = "\"BẠN ĐANG Ở ĐÂY\""
textfix["INSTALLING \"BOBBER\" ADDON TO FISHINGROD.EXE"] = "CÀI ĐẶT THÊM \"BOBBER\" VÀO FISHINGROD.EXE"
